from 写入第二遍 import add
add('13_002',6,'16:9，跟随武士头部的斜侧极特写，椭圆弧面占画面左侧到中央，黑隙与白眼留在右上，边缘被短振线割开；镜头以同速横移稳住眼睛，落幅停在眼珠偏向青的一侧。','武士的头在受力余势里侧歪，白眼先猛地定住，再向青所在的胸侧急移；眼隙边缘不规则地收缩，几枚深灰细屑从头侧向后拖走。第一声内心惊问掠过时，他试图抬正头部，刚抬一小截便被下一次贴身拳风逼回；内心衡量力量速度时，眼珠的转动逐渐变小，只追得住青发梢掠过的一道浅影。','头部右侧仅余浅冷灰白图形底，向后拖去的深灰细点形成短尾，云天纹理压得很淡。','同场冷白光覆盖头部弧面，眼隙深黑、白眼高反差；受力时轮廓亮暗短促交替。','拳风在头侧近近掠过，厚重呼吸被迫断一下，细屑擦过风声。',ja=['何だこれは…？！','力も速さも、さっきとはまるで桁が違う…！'],tone='内心第一句骤然惊问；第二句急促比较，重音逐步落到力量、速度与差距，尚未找到回应。',kind='mixed',phase='reaction',node={'叙事阶段':'武士受击惊觉青已全面强化'},meaning='武士白眼震惊与两句内心判断完整保留，受击后的视线追逐接连续拳击。',motion='镜头追随横向飞行，武士头向一边歪、眼珠追青，后方细屑同向拖走。',ground='仍在平台上方横移，尚未发生新的落地接触。',characters=['鬼头武士'],card={'opening':'先前的自信被第一拳打断。','beats':['白眼定住再急移，第一句内心惊问','试抬头又被拳风压回','判断差距时眼珠越来越跟不上'],'coupling':'内心不是嘴部说话，眼神与受力余势贯穿两句。','landing':'青已压到近身，武士没能形成反击。'})
add('14_001',3,'16:9，青侧后方的双人中景，青躯干与收展双臂占画面右侧，武士头胸占左后；机位贴着青肩后小幅追移，落幅把肩、胸、腹的连续击点和青发梢收进同一框。','青贴住武士胸侧，转腰送出一组快拳：肩侧两下、胸口两下，再把拳线压低扫到腹侧两下，三组之间只留极短收拳空隙。每一拳到位，武士对应部位才爆出一枚短白冲击形，头胸左右摇开；青另一只手随出拳交替护回身前，发束与裙侧被连转的腰胯拖成弧，最后一拳收回时身体开始下降。','人物外侧是深蓝灰速度图形底，浅冷灰放射短线随各次击点散开，边缘极窄一带石铺地面显示距离平台很近。','人物保持云天冷白光，白色冲击形只在各次接触瞬间出现；深灰主体轮廓在连续受力中清楚分离。','六记紧凑闷击分成二、二、二三组，护腕布料急绷、发梢破风夹在组间。',node={'叙事阶段':'青完成肩胸腹三组连续拳击，准备落脚转上踢'},meaning='青贴身连续拳击与武士多点白色爆形保留，各爆点是依次命中。',motion='青由肩高压到腹侧，武士仍顺横向受力晃动，摄影机始终在青侧后方追住。',ground='近地短暂离地状态，最后青身体下落，下一镜支撑足着地。',characters=['青','鬼头武士'])
add('14_002',1,'16:9，青支撑脚的贴地特写，足底在画面中央偏左压入石面，足踝从右上斜入；固定机位，两道白色弧线从左右擦过前后层。','青支撑脚先以前掌压到石面，再迅速把全脚踩实，膝踝随之沉下一小截；鞋底边缘将两粒碎石压开，板缝挤出一线灰尘。两道先前旋身的白弧越过脚侧，足踝在沉到最低的一刻绷住，蓄力转向上方。','灰绿石铺地面铺满画幅，足下接触处深灰，板缝边缘有小块米灰碎屑，远层石纹柔化。','上方冷白漫射让足面与脚下短影分开，灰尘保持米灰。','鞋底重压石面一声短实响，碎石轻崩，风声在踩实瞬间收紧。',phase='contact',node={'叙事阶段':'青支撑足踩实蓄力','青.位置':'石面着地，准备上踢'},meaning='用户确认的支撑脚踩实；足底接触、石纹与白色弧线保留，向上踢转换。',motion='足由右上斜落至中央，压实后脚踝向上蓄紧，弧线从两侧掠过。',ground='青支撑脚完整着地承重，另一腿在画外准备踢出。',characters=['青'])
